package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.SerializedString;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonObjectFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.ser.BeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.UnwrappingBeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.std.StringSerializer;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class BeanPropertyWriter_serializeAsColumn_TriageGen2Test {

    private BeanPropertyWriter writer;
    private JsonGenerator jgen;
    private SerializerProvider prov;
    private PropertySerializerMap map;

    // Marker constant used in the method logic
    private static final Object MARKER_FOR_EMPTY = new Object();

    @Before
    public void setUp() throws Exception {
        // BeanPropertyWriter is typically created via a factory or internal Jackson processes.
        // Since the constructor is protected, we use a mock or a subclass for testing.
        writer = spy(new TestBeanPropertyWriter());
        jgen = mock(JsonGenerator.class);
        prov = mock(SerializerProvider.class);
        map = mock(PropertySerializerMap.class);

        // Inject the map through reflection since it's a private field in the real class
        setInternalField(writer, "_dynamicSerializers", map);
    }

    /**
     * Test Case 1: Value is null, no null serializer assigned.
     * Expected: jgen.writeNull() is called.
     */
    @Test
    public void testSerializeAsColumn_NullValue_NoNullSerializer() throws Exception {
        doReturn(null).when(writer).get(any());
        setInternalField(writer, "_nullSerializer", null);

        writer.serializeAsColumn(new Object(), jgen, prov);

        verify(jgen).writeNull();
    }

    /**
     * Test Case 2: Value is null, null serializer is assigned.
     * Expected: _nullSerializer.serialize(null, jgen, prov) is called.
     */
    @Test
    public void testSerializeAsColumn_NullValue_WithNullSerializer() throws Exception {
        JsonSerializer<Object> nullSer = mock(JsonSerializer.class);
        doReturn(null).when(writer).get(any());
        setInternalField(writer, "_nullSerializer", nullSer);

        writer.serializeAsColumn(new Object(), jgen, prov);

        verify(nullSer).serialize(eq(null), eq(jgen), eq(prov));
    }

    /**
     * Test Case 3: Value is non-null, serializer is already assigned.
     * Expected: ser.serialize(value, jgen, prov) is called.
     */
    @Test
    public void testSerializeAsColumn_NonNull_SerializerExists() throws Exception {
        Object value = "test";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        doReturn(value).when(writer).get(any());
        setInternalField(writer, "_serializer", ser);
        setInternalField(writer, "_typeSerializer", null);

        writer.serializeAsColumn(new Object(), jgen, prov);

        verify(ser).serialize(value, jgen, prov);
    }

    /**
     * Test Case 4: Value is non-null, serializer is not assigned, found in map.
     * Expected: ser.serialize(value, jgen, prov) is called.
     */
    @Test
    public void testSerializeAsColumn_NonNull_FindInMap() throws Exception {
        Object value = "test";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        doReturn(value).when(writer).get(any());
        setInternalField(writer, "_serializer", null);
        when(map.serializerFor(value.getClass())).thenReturn(ser);
        setInternalField(writer, "_typeSerializer", null);

        writer.serializeAsColumn(new Object(), jgen, prov);

        verify(ser).serialize(value, jgen, prov);
    }

    /**
     * Test Case 5: Value is non-null, serializer is not assigned, not in map, findAndAddDynamic called.
     * Expected: _findAndAddDynamic is called.
     */
    @Test
    public void testSerializeAsColumn_NonNull_FindAndAddDynamic() throws Exception {
        Object value = "test";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        doReturn(value).when(writer).get(any());
        setInternalField(writer, "_serializer", null);
        when(map.serializerFor(value.getClass())).thenReturn(null);
        doReturn(ser).when(writer)._findAndAddDynamic(eq(map), eq(value.getClass()), eq(prov));
        setInternalField(writer, "_typeSerializer", null);

        writer.serializeAsColumn(new Object(), jgen, prov);

        verify(writer)._findAndAddDynamic(map, value.getClass(), prov);
        verify(ser).serialize(value, jgen, prov);
    }

    /**
     * Test Case 6: Suppressable value is MARKER_FOR_EMPTY and value is empty.
     * Expected: serializeAsPlaceholder is called.
     */
    @Test
    public void testSerializeAsColumn_SuppressEmpty() throws Exception {
        Object value = ""; // Assuming String is "empty"
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        doReturn(value).when(writer).get(any());
        setInternalField(writer, "_serializer", ser);
        setInternalField(writer, "_suppressableValue", MARKER_FOR_EMPTY);

        when(ser.isEmpty(value)).thenReturn(true);

        writer.serializeAsColumn(new Object(), jgen, prov);

        verify(writer).serializeAsPlaceholder(any(), eq(jgen), eq(prov));
        verify(ser, never()).serialize(any(), any(), any());
    }

    /**
     * Test Case 7: Suppressable value matches exact value.
     * Expected: serializeAsPlaceholder is called.
     */
    @Test
    public void testSerializeAsColumn_SuppressExactValue() throws Exception {
        Object value = "special";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        doReturn(value).when(writer).get(any());
        setInternalField(writer, "_serializer", ser);
        setInternalField(writer, "_suppressableValue", "special");

        writer.serializeAsColumn(new Object(), jgen, prov);

        verify(writer).serializeAsPlaceholder(any(), eq(jgen), eq(prov));
    }

    /**
     * Test Case 8: Self reference (value == bean).
     * Expected: _handleSelfReference is called.
     */
    @Test
    public void testSerializeAsColumn_SelfReference() throws Exception {
        Object bean = new Object();
        doReturn(bean).when(writer).get(bean);
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        setInternalField(writer, "_serializer", ser);
        setInternalField(writer, "_typeSerializer", null);

        writer.serializeAsColumn(bean, jgen, prov);

        verify(writer)._handleSelfReference(eq(bean), eq(ser));
        verify(ser).serialize(bean, jgen, prov);
    }

    /**
     * Test Case 9: Type serializer is present.
     * Expected: ser.serializeWithType(value, jgen, prov, typeSer) is called.
     */
    @Test
    public void testSerializeAsColumn_WithTypeSerializer() throws Exception {
        Object value = "test";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        JsonSerializer<Object> typeSer = mock(JsonSerializer.class);
        doReturn(value).when(writer).get(any());
        setInternalField(writer, "_serializer", ser);
        setInternalField(writer, "_typeSerializer", typeSer);

        writer.serializeAsColumn(new Object(), jgen, prov);

        verify(ser).serializeWithType(value, jgen, prov, typeSer);
    }

    // Helper class to allow instantiation and spying
    private static class TestBeanPropertyWriter extends BeanPropertyWriter {
        protected TestBeanPropertyWriter() {
            super(null); // This is a hack because the constructor is protected
        }

        @Override
        public Object get(Object bean) throws Exception {
            return super.get(bean);
        }

        @Override
        protected JsonSerializer<Object> _findAndAddDynamic(PropertySerializerMap map, Class<?> type, SerializerProvider provider) {
            return null;
        }

        @Override
        protected void _handleSelfReference(Object bean, JsonSerializer<?> ser) {
            // No-op
        }

        @Override
        public void serializeAsPlaceholder(Object bean, JsonGenerator jgen, SerializerProvider prov) throws Exception {
            // No-op
        }
    }

    private void setInternalField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
